package com.d4cx.tvlauncher;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.net.*;import java.io.*;import java.nio.charset.StandardCharsets;
final class WeatherWidget extends LinearLayout {
 static final long HOUR=3600000L;static final String ENDPOINT="https://api.open-meteo.com/v1/forecast?latitude=33.55808&longitude=-7.48647&current=temperature_2m,weather_code,is_day&timezone=Africa%2FCasablanca&forecast_days=1";
 final Activity activity;final SharedPreferences cache;final Handler main=new Handler(Looper.getMainLooper());final WeatherIcon icon;final TextView weather;final LinearLayout row;
 boolean active=false,loading=false,destroyed=false;long attempted=0;final Runnable tick=()->refresh();
 int d(int n){return UI.dp(getContext(),n);}
 WeatherWidget(Activity a){super(a);activity=a;cache=a.getSharedPreferences("weather_tit_mellil",Context.MODE_PRIVATE);setOrientation(VERTICAL);setGravity(Gravity.RIGHT);
  TextClock date=new TextClock(a);date.setFormat12Hour("EEEE, MMM d");date.setFormat24Hour("EEEE, MMM d");date.setTextSize(11);date.setTextColor(0xffaaaaaa);date.setGravity(Gravity.RIGHT);addView(date,new LayoutParams(-1,d(23)));
  row=new LinearLayout(a);row.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);row.setFocusable(true);row.setFocusableInTouchMode(true);row.setClickable(true);row.setOnClickListener(v->details());row.setOnFocusChangeListener((v,f)->{row.setAlpha(f?1:.85f);row.setBackground(f?UI.bg(0x55333333,0):null);});addView(row,new LayoutParams(-1,d(29)));
  icon=new WeatherIcon(a);row.addView(icon,new LayoutParams(d(26),d(26)));weather=UI.text(a,"Weather loading…",12,0xffdddddd);weather.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);LayoutParams p=new LayoutParams(-2,-1);p.leftMargin=d(7);row.addView(weather,p);display();
 }
 void display(){long saved=cache.getLong("updated",0);boolean valid=saved>0&&System.currentTimeMillis()-saved<6*HOUR;if(!valid){icon.update(-1,true);weather.setText(saved>0?"Weather unavailable":"Weather loading…");return;}int code=cache.getInt("code",-1);boolean day=cache.getBoolean("day",true);WeatherCondition c=WeatherCondition.from(code,day);icon.update(code,day);String text=cache.getInt("temperature",0)+"° · "+c.label;if(System.currentTimeMillis()-saved>HOUR)text+=" · cached";weather.setText(text);row.setContentDescription("Tit Mellil: "+text);}
 void resume(){active=true;display();refresh();}
 void pause(){active=false;main.removeCallbacks(tick);}
 void close(){destroyed=true;pause();main.removeCallbacksAndMessages(null);}
 void refresh(){main.removeCallbacks(tick);if(!active||destroyed)return;long now=System.currentTimeMillis(),saved=cache.getLong("updated",0);long age=now-saved;if(saved>0&&age>=0&&age<HOUR){main.postDelayed(tick,HOUR-age);return;}if(loading)return;if(now-attempted<600000){main.postDelayed(tick,600000-(now-attempted));return;}loading=true;attempted=now;
  new Thread(()->{boolean success=false;HttpURLConnection connection=null;try{connection=(HttpURLConnection)new URL(ENDPOINT).openConnection();connection.setConnectTimeout(6000);connection.setReadTimeout(6000);connection.setRequestProperty("User-Agent","MonoTV/2.7 personal weather");if(connection.getResponseCode()!=200)throw new IOException("Weather request failed");ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(InputStream input=connection.getInputStream()){byte[] buffer=new byte[2048];int n;while((n=input.read(buffer))!=-1){if(bytes.size()+n>32768)throw new IOException("Weather response too large");bytes.write(buffer,0,n);}}JSONObject current=new JSONObject(new String(bytes.toByteArray(),StandardCharsets.UTF_8)).getJSONObject("current");double temp=current.getDouble("temperature_2m");int code=current.getInt("weather_code");if(!Double.isFinite(temp)||temp< -100||temp>70||WeatherCondition.from(code,true).kind.equals("unknown"))throw new IOException("Invalid weather");cache.edit().putInt("temperature",(int)Math.round(temp)).putInt("code",code).putBoolean("day",current.getInt("is_day")==1).putLong("updated",System.currentTimeMillis()).apply();success=true;}catch(Exception ignored){}finally{if(connection!=null)connection.disconnect();}final boolean ok=success;main.post(()->{loading=false;if(destroyed)return;display();if(!ok&&cache.getLong("updated",0)==0){weather.setText("Weather unavailable");icon.update(-1,true);}if(active)main.postDelayed(tick,ok?HOUR:600000);});},"WeatherFetch").start();
 }
 void details(){long timestamp=cache.getLong("updated",0);String updated=timestamp==0?"Waiting for a weather reading":android.text.format.DateFormat.getDateFormat(activity).format(new java.util.Date(timestamp))+" "+android.text.format.DateFormat.getTimeFormat(activity).format(new java.util.Date(timestamp));new AlertDialog.Builder(activity).setTitle("Tit Mellil · Weather").setMessage("Current conditions: "+weather.getText()+"\n\nLast updated: "+updated+"\n\nRefreshes hourly while Home is visible. Weather estimates may differ from conditions at your exact location.\n\nWeather data: Open-Meteo.com · CC BY 4.0").setPositiveButton("Done",null).show();}
}
